WFJ.Data.add("gossip", {
  ["630994914c20f32d"] = { "Elder BellowrageはBlasted Landsの尾根からDark Portalを見守っている。", "." },
  ["6313f430627cb54f"] = { "暑さなど気にするな。Badlandsでは、暑さなど悩みのうちで一番小さなものだ。", "." },
  ["631437af1bd58425"] = { "全部持ってたんだ！全部持ってたのに、失くしちまった。失くした……全部消えた……まるで……俺の正気みたいに。俺の頭は……チーズみたいだ。チーズは好きだ。", "." },
  ["63180f3eed6399c1"] = { "我らは使命から揺らぐことはない！", "." },
  ["63237b46a51def96"] = { "パイロンをよく調べてみると、小さな台があり、その上に黄色、赤、緑のクリスタルが何か特定の配置のように並べられているのが見つかった。\n\n大きな黄色のクリスタルの円の片側には小さな赤いクリスタルの円が、もう片側には緑のクリスタルの円が並んでいる。\n\nあなたはクリスタルの色を注意深く書き留めた。J.D.があなたの発見について聞けば、きっと大いに興味を持つだろう。", "." },
  ["632419adfa2ea29d"] = { "私はお前のすぐ隣に立っていたのだぞ、愚か者め。お前が何を求めているかは分かっている。", "." },
  ["632ab041747c7123"] = { "小銭を恵んでくれんかね？", "." },
  ["632e58a8ef571d76"] = { "あなたはより高い知識を求めているのですね。Tepaはそのような知識に恵まれています。彼女はこの近くのどこかに立っているはずです……", "." },
  ["63331c68673d9178"] = { "ああ、そいつはAustil de Monだな。いつも町の南東の端にある酒場に入り浸ってるよ。Gallows' End Tavernっていうんだ、すぐ分かるさ。", "." },
  ["635624c4e75949ab"] = { "素晴らしい! これはただちに使者でUndercityへ送らせよう!\n\nお前にはな――約束どおり、ここに支払いがある。釣りは取っておけ、この薄汚い獣め!", "." },
  ["635d1cf61926684f"] = { "お前さんには聞きたいことがあるが、どれも俺には答えられねえほどでかい話だ、{name}。OrgrimmarのDragにいるオークのYelmakと話さなきゃならねえ。あいつが助けてくれるさ。", "." },
  ["635e9436140580a6"] = { "%sはもう呪文を唱えられないようだ。Felcurseが効いている！", "." },
  ["6362329550d11bb9"] = { "私はUlysses Rackmore、Gallantの船長だ。そしてこれは、我が不運な船の最後の数日間の航海日誌である。\n\n我々は補給物資を積んでFeathermoon Strongholdへ航行していたが、nagaがGallantの舷側に襲いかかってきた。我々は奴らを撃退したが、また戻ってくることは分かっていた。最も大切な持ち物を失うことを恐れ、私はGallantを、Desolace沖にある古いナイトエルフの遺跡がある島へと向かわせた。そしてそこに我が宝箱を残したのだ。", "." },
  ["636b9a885815d2b9"] = { "わかっただろう？今すぐ中に入れ。", "." },
  ["636c67a0248dfa00"] = { "まずいことになったぞ！", "." },
  ["636e2ca25052dde6"] = { "%sはBlackhand Veteranの召喚を始めた！", "." },
  ["637660accaa947cd"] = { "この樽を発掘現場まで運ぶのは重労働だが、爆薬がそこへ届くのを待っている者がたくさんいるんだ。\n\nDark Ironsに対して、できることをしなければ!", "." },
  ["637e46c84c61e0fb"] = { "死のとぐろがお前を締め潰すであろう！", "." },
  ["637f52329139faeb"] = { "ついに――汝らの中に我が知識にふさわしい者が現れたか。案ずるな――汝の思考は探らせてもらった、危害は加えぬ。", "." },
  ["638283b9588f4ea3"] = { "ああ、お前を見ただけで分かったぞ、{name}。お前を見ていると、Hordeの若きウォリアーだった頃の自分を思い出す。\n\nお前はきっと人生で遠くまで行くだろう。そして死してなお、さらに遠くへな。\n\n<Goretoothが敬礼する。>", "." },
  ["6382a27f434c2727"] = { "Westfallに邪悪な腐敗が忍び寄っている。私がLordaeronの戦場で務めを果たしている間に、これらの誠実な農場は踏みにじられ、悪党や人殺しどもの隠れ家にされてしまった。People's Militiaには君の助けが必要だ。", "." },
  ["638c39269736fe64"] = { "お前の知り合いか？", "." },
  ["638d1cdc2b0e1d69"] = { "Rexxar、Drakefire Amuletをなくしてしまった。もう一つ作ってもらえないだろうか?", "." },
  ["638d695ce413ac71"] = { "寝てろ！", "." },
  ["639019ab179ca3f5"] = { "決して許しはしません……かつて我々は彼をこの世界から追放しました。そして再び追放してみせます。", "." },
  ["6393c563f1613c8b"] = { "悪いが、私はローグしか訓練しないんだ。", "." },
  ["639b7cec4bd16ffb"] = { "ついに、我が魂は自由になった!", "." },
  ["639d63717491bf0b"] = { "Hordeが鉱山を奪った！", "." },
  ["63a2eed0217e73f1"] = { "すべて集まり、Silithusへ送られているところです、{class}。$2113w日以内に届くはずです。銅鑼が鳴らされ、門が開かれた後、ここでの私たちの努力が効果を上げ、多くの命を救うことをただ願うばかりです。", "." },
  ["63a40695969f59fa"] = { "いつでも行けるよ、{name}。先導してくれ！", "." },
  ["63aed17fed8b0ec8"] = { "冒涜者め……この侵入の罰を受けるがいい。<遺物から炎の紋章が放たれ、遺物は崩れて土に還った。>", "." },
  ["63b12f55accfc261"] = { "あの間抜けなcentaurどもめ！はあ――まあ、約束は守ったようだな。この道を上るとSmeed Scrabblescrewがいる。そいつが金を持ってる。", "." },
  ["63b18d28a667e7fa"] = { "さて、今日は何をしたい？", "." },
  ["63b305db24cfaf3e"] = { "焦点を12か所に置けば、魔力がもっと固く形を成して、必要な安定が得られるかもしれない。", "." },
  ["63bc2f70838f2b70"] = { "急げ、兄弟たち！今すぐ行くのだ！裂け目があとどれだけ開いているかわからない！", "." },
  ["63c4b5a0ce6eb26b"] = { "一緒にいてくれるのはありがたいけど、正直に言おう。ポーションについては君のほうが私より経験豊富だ。訓練を受けたいなら、代わりにDoctor Marshと話してくれ。彼はUndercityのApothecariumにいるForsakenだ。", "." },
  ["63c71666355672bc"] = { "準備した物資はSilithusへ船で送られていて、$2113w日もかからずに全部届くと聞いた。あの虫どもが俺の鉱山に穴を掘って入ってくるのは見たくないからな、誰かが時間をかけてScepter of the Shifting Sandsを組み上げて、銅鑼が鳴らされ、門が開かれ、ついに戦争が始まることを願ってるよ。", "." },
  ["63c9400850d02b07"] = { "おぉ……よく来た{name}よ。\n\n精神と肉体の結びつきについて、そなたは知るだろう。強さは山として、忍耐は平原として、そしてそなたの本質は世界そのものとして。\n\nこの儀式を通るには、謙虚な心でEarthの前に立つことだ。しかし、他の場合にはそうではないかもしれない。時に混沌と、時に凶暴に、それがelementsの性質だ。互いに反する性質を困難を持って学んでいかなくてはならない。", "." },
  ["63d0c3cfee154cca"] = { "ウォリアーならたいてい、Pig and Whistle TavernかOld TownのBarracksにいるよ。でもな、探すなら酒場のほうがいいと思うぜ。", "." },
  ["63e6b64c9b713b33"] = { "まだ着かないの？", "." },
  ["63eb893478cf6f9f"] = { "Eyeに導かれてここへ来ました、Eris。", "." },
  ["63ed14612e4765b3"] = { "愛のしるしは、恋に浮かれた町や都市の人々に渡せる、ささやかな愛情のメッセージだ。そういう人々は、お礼に敬愛の贈り物をくれる。\n\nあるいは、あなたがすでに別の誰かに想われているなら、少なくとも友情の贈り物はくれるだろう。", "." },
  ["63f0b1c90c89e4ff"] = { "下がって……息を止めてくれ。これをやるのは久しぶりなんだ。", "." },
  ["63f5b9270205bc05"] = { "呪われた姿でこれほど長くさまよってきました。あなたが私を解放してくれたのです……あなたの苦労は報われるでしょう。", "." },
})
